function canonicalJson(value: any): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

/** Ensures the detached metadata asset is the checksummed, archive-bound form of package metadata. */
export function validateCompatibilityAssetBinding(
  external: ReleaseCompatibilityMetadata,
  embedded: ReleaseCompatibilityMetadata,
  expectedVersion: string,
  expectedArchive: string,
  actualArchiveSha256: string,
  platformKey = "linux-x86_64"
  BaselineSpecification,
  BaselineComparisonResult,
  ComparativeOutcome,
} from "./contracts.js";

function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  if (value && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : 1));
    return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${canonicalJson(v)}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

const SHA256_HEX = /^[0-9a-f]{64}$/;
const MODEL_DIGEST = /^sha256:[0-9a-f]{64}$/;

/** Sampling values that are undefined, null or not finite are treated as absent. */
function normalizeSampling(sampling: BaselineIdentity["sampling"]): BaselineIdentity["sampling"] {
  return Object.fromEntries(
    Object.entries(sampling ?? {}).filter(([, v]) => v !== undefined && v !== null && !(typeof v === "number" && !Number.isFinite(v))),
  ) as BaselineIdentity["sampling"];
}

function sha256(value: unknown): string {
  return createHash("sha256").update(canonicalJson(value)).digest("hex");
}

export class CeriBaselineComparator {
  return d as EvaluationDefinition;
}

/**
 * Deterministically serializes any JavaScript object to canonical JSON with recursively sorted keys.
 * Correctly preserves all nested object properties without dropping fields.
